UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 40, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 41, 15, NULL::text),(3, 177, 43, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 224, 256, NULL::text),(6,0,0,E'a) Llantas delanteras. Las llantas de la dirección deben tener una profundidad de dibujo igual o mayor a 3.2 mm (1/8") medida a lo largo de una banda circunferencial sobre el dibujo de todas las ranuras principales a lo ancho de la llanta.</td><td></td><td></td><td></td></tr><tr><td>b) Llantas traseras. Las llantas en los ejes que no son de dirección deben tener una profundidad del dibujo igual o mayor a 1.6 mm (1/16") medida a lo largo de una banda de circunferencia continua sobre el dibujo de todas las ranuras principales a lo ancho de la llanta.'),(7, 1044, 591, NULL::text),(8,0,0,E'c) La banda de rodamiento de la llanta debe estar libre de cortes mayores a 25 mm (1,0") que afecten el cuerpo de cuerdas.'),(9, 1762, 695, NULL::text),(10,0,0,E'h) Las llantas en montaje dual deben estar separadas entre sí y no variar más de: Llanta diagonal cuya anchura de sección sea de 228,6 mm (9,00") y mayores: 12 mm (0,47") en su diámetro total o 37,7 mm (1,48'''') en circunferencia y llantas cuya anchura de sección sea de 209,5 mm (8,25'''') y menores: 8 mm (0,31'''') en su diámetro total o 25,13 mm (0,99'''') en circunferencia. Llanta radial cuya anchura de sección sea de 228,6 mm (9,00") y mayores: 8 mm (0,31") en su diámetro total o 25,13 mm (0,99'''') en circunferencia y llantas cuya anchura de sección sea de 209,5 mm (8,25'''') y menores: 6 mm (0,24'''') en su diámetro total o 18,8 mm (0,74'''') en circunferencia.'),(11, 3137, 150, NULL::text),(12,0,0,E'j) En caso de que la llanta presente cortes en su superficie de rodamientos, deben ser menores a 25 mm (1") de longitud por debajo de la profundidad del dibujo o cortes en las cuerdas. - La llanta debe encontrarse sin pedazos faltantes de más de 625 mm² (1 in²).'),(13, 3554, 590, NULL::text),(14,0,0,E'n) Todas las llantas renovadas instaladas en el vehículo deben tener la indicación "Renovada".'),(15, 4248, 407, NULL::text),(16,0,0,E'b) El costado de las llantas debe estar libre de abultamientos de altura mayor a 9.5 mm (3/8").'),(17, 4755, 570, NULL::text),(18,0,0,E'f) Los vehículos deben equiparse con llantas que no porten el mensaje "PARA USO EXCLUSIVO EN AGRICULTURA", "PARA USO EXCLUSIVO EN CIRCUITO DE COMPETICIÓN" o cualquier otro mensaje o aviso como "SL", "NHS" o "TG" (siglas en inglés) a continuación de la designación de la llanta.'),(19, 5652, 2167, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='e37aa998-256e-5f11-a3bf-fba905c06025' AND md5(a.contenido)='ee285e5c3e696dcc3078730283bec0c8' RETURNING a.id,md5(a.contenido) hash;